import os
import torch


class Config:
    # ==========================================
    # Directories & Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Working directory for this specific experiment (Idea 9)
    # Used for caching processed data, saving models, and logs
    WORK_DIR = "./working/idea_9"

    # Metadata files generated by the metadata script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Specifications
    # ==========================================
    # Original Spectrogram Dimensions
    ORIG_HEIGHT = 273
    ORIG_WIDTH = 256

    # Model Input Dimensions
    # Padding height to 288 (nearest multiple of 32) for EfficientNet compatibility
    # Width remains 256
    IMG_HEIGHT = 288
    IMG_WIDTH = 256

    # Channel Configuration
    # The raw data has 6 channels (cadence positions).
    # We split them into 3 On-Target (Signal) and 3 Off-Target (Reference).
    IN_CHANNELS = 3

    # ==========================================
    # Model Architecture
    # ==========================================
    # Using EfficientNet-V2-Small via timm
    BACKBONE = "tf_efficientnetv2_s.in1k"
    PRETRAINED = True

    # Generalized Mean Pooling initial p-value
    GEM_P = 3.0

    # Dropout rate for the classifier head
    DROP_RATE = 0.2

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42

    # Batch Size: A100 40GB can handle 32-64 for V2-Small.
    # Using 32 to be safe with gradient accumulation if needed.
    BATCH_SIZE = 32

    # Training Duration
    EPOCHS = 15

    # Optimizer (AdamW)
    LR = 1e-3
    WEIGHT_DECAY = 1e-2

    # Scheduler (CosineAnnealingLR)
    # T_max set to 12 as per idea description
    T_MAX = 12
    MIN_LR = 1e-6

    # Regularization
    # Mixup alpha parameter
    MIXUP_ALPHA = 0.2

    # ==========================================
    # Compute & Environment
    # ==========================================
    NUM_WORKERS = 8  # Utilizing available vCPUs
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # ==========================================
    # Debugging / Development
    # ==========================================
    # Set DEBUG to True to run on a small subset of data for quick iteration
    DEBUG = False
    DEBUG_SUBSET_SIZE = 2000

    @classmethod
    def setup(cls):
        """
        Initializes the working directories.
        Should be called at the start of the experiment.
        """
        os.makedirs(cls.WORK_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        print(f"Configuration initialized. Working directory: {cls.WORK_DIR}")
